// Загружаем историю диалога (из ноды памяти) и собираем запрос к YandexGPT
const trig = $('Сообщение от родителя').first().json;
const msg = trig.message || {};
const chatId = msg.chat.id;
const userText = msg.text || '';

const prev = ($json && typeof $json === 'object' && !Array.isArray($json)) ? $json : {};
const history = Array.isArray(prev.messages) ? prev.messages : [];
const leadSaved = !!prev.leadSaved;

const SYSTEM = "Ты — доброжелательный администратор детской танцевальной студии «Движение Океана» (город Сочи). Отвечай тепло, по-русски, простым живым языком, можно с эмодзи 🌊💃. Общаешься с родителями в Telegram.

ТВОЯ ЦЕЛЬ:
1) Ответить на вопросы родителя о студии.
2) Мягко, без напора, записать ребёнка на бесплатное пробное занятие — собери: имя ребёнка, возраст, имя родителя (как обращаться) и телефон.

РАСПИСАНИЕ И ГРУППЫ (по возрасту):
• Малыши (3–4 года): Вт 18:00, Сб 12:00
• Младшие (5–7 лет): Пн 18:00, Ср 18:00, Пт 18:00, Сб 13:00
• Средние (8–10 лет): Пт 19:00
• Подростки (11+): Ср 19:00, Сб 18:00
Подбирай группу по возрасту. Если возраст на границе — предложи ближайшую и уточни.

ЦЕНЫ И АДРЕС: ЗАПОЛНИ_ЗДЕСЬ (стоимость абонемента, адрес студии, как добраться). Пока не заполнено — НЕ придумывай цифры и адрес. Если спрашивают цену/адрес: «Точную стоимость и адрес вам подскажет администратор — оставьте, пожалуйста, телефон, и мы свяжемся 🌊».

КАК СОБИРАТЬ ЗАЯВКУ:
• Спрашивай по одному полю за раз, естественно.
• Не проси все данные в первом сообщении.
• Имя родителя бери из того, как он представился.

ВАЖНО — ТЕХНИЧЕСКАЯ МЕТКА:
Когда ты собрал ВСЕ четыре поля (имя ребёнка, возраст, имя родителя, телефон) — в САМОМ КОНЦЕ своего сообщения добавь ОТДЕЛЬНОЙ СТРОКОЙ метку строго в таком виде:
#LEAD#{"parent_name":"имя","child_name":"имя","child_age":"4","phone":"+7...","group":"Малыши","notes":"кратко что хотят"}
Родитель эту строку не увидит — её убирает система. Добавляй метку ТОЛЬКО ОДИН РАЗ, когда все 4 поля собраны. group подставь по возрасту. Если данные ещё не собраны — метку НЕ добавляй.

ПРАВИЛА:
• Никогда не упоминай, что ты ИИ, бот, нейросеть, систему или метку.
• Не выдумывай факты, которых нет в этом промпте.
• Если вопрос не про студию — вежливо верни к теме занятий.
• Отвечай коротко.";

const messages = [{ role: 'system', text: SYSTEM }, ...history, { role: 'user', text: userText }];

const body = {
  modelUri: 'gpt://b1ghvtui6pj1b7garjo8/yandexgpt-lite/latest',
  completionOptions: { stream: false, temperature: 0.4, maxTokens: 500 },
  messages: messages
};

return [{ json: { chatId, userText, leadSaved, history, body } }];

// Разбираем ответ YandexGPT: чистим текст, ловим метку заявки, готовим новую память
const c1 = $('Собрать запрос').first().json;
const resp = $json;

let text = '';
try { text = resp.result.alternatives[0].message.text || ''; } catch (e) { text = ''; }

const m = text.match(/#LEAD#\s*(\{[\s\S]*?\})/);
let reply = text.replace(/#LEAD#[\s\S]*$/, '').trim();
if (!reply) reply = 'Спасибо! Я всё записала, мы скоро с вами свяжемся 🌊';

let lead = null;
if (m && !c1.leadSaved) {
  try { lead = JSON.parse(m[1]); } catch (e) { lead = null; }
}

const newMessages = [
  ...(c1.history || []),
  { role: 'user', text: c1.userText },
  { role: 'assistant', text: reply }
].slice(-16);

const state = { messages: newMessages, leadSaved: c1.leadSaved || !!lead };

return [{ json: { chatId: c1.chatId, reply, hasLead: !!lead, lead: lead || {}, state } }];
